  gorsel: null,
  secenekler: ["Alt kattaki çocuk merdivenlerde düştü.", "Deniz her akşam yatmadan önce okur.", "Misafirler akşam yemeğinden sonra evden ayrıldı.", "Bebek beşiğinde derin derin uyudu."],
